const aiRaw = $("AI Qualification").first().json.output;
const userInput = String($("When Executed by Another Workflow").first().json.input || "").toLowerCase();

function stripMarkdown(text) {
  return String(text || "")
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
}

function extractFirstJsonObject(text) {
  const s = stripMarkdown(text);

  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (ch === "\\") {
        escaped = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }

    if (ch === '"') {
      inString = true;
      continue;
    }

    if (ch === "{") {
      if (depth === 0) start = i;
      depth++;
      continue;
    }

    if (ch === "}") {
      depth--;
      if (depth === 0 && start !== -1) {
        return s.slice(start, i + 1);
      }
    }
  }

  return null;
}

function safeParseAiOutput(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value;
  }

  if (Array.isArray(value)) {
    const firstWithOutput = value.find(item => item && typeof item === "object" && item.output);
    if (firstWithOutput) {
      value = firstWithOutput.output;
    } else {
      return null;
    }
  }

  if (typeof value !== "string") return null;

  const cleaned = stripMarkdown(value);

  try {
    return JSON.parse(cleaned);
  } catch {}

  const firstJson = extractFirstJsonObject(cleaned);
  if (firstJson) {
    try {
      return JSON.parse(firstJson);
    } catch {}
  }

  return null;
}

function sanitizeTextToUser(parsed, raw) {
  if (parsed && typeof parsed.text_to_user === "string" && parsed.text_to_user.trim()) {
    return parsed.text_to_user.trim();
  }

  const firstJson = typeof raw === "string" ? extractFirstJsonObject(raw) : null;
  if (firstJson) {
    try {
      const reparsed = JSON.parse(firstJson);
      if (typeof reparsed.text_to_user === "string" && reparsed.text_to_user.trim()) {
        return reparsed.text_to_user.trim();
      }
    } catch {}
  }

  return "Понял ваш запрос. Чтобы продолжить, уточню один короткий момент: какая цель сейчас в приоритете?";
}

const parsed = safeParseAiOutput(aiRaw) || {
  status: "error_fallback",
  is_qualified: false
};

const consultIntent = /(цена|стоим|сколько|бонус|скидк|разниц|сравн|какой лучше|какой вариант|вариант|продукт|выбираю|выбрал|спринт|практикум|резидент)/i.test(userInput);

let recommendedNextStep = parsed.status === "completed" ? "consult" : "wait_for_reply";
if (parsed.status !== "completed" && consultIntent) {
  recommendedNextStep = "consult";
}

return {
  ...parsed,
  text_to_user: sanitizeTextToUser(parsed, aiRaw),
  lead_id: $("When Executed by Another Workflow").first().json.lead_id,
  recommended_next_step: recommendedNextStep
};

